refentry.refsect1:
  &reftitle.examples;



    Esempio di token_get_all


<?php
$tokens = token_get_all('<?php echo; ?>');

foreach ($tokens as $token) {
    if (is_array($token)) {
        echo "Riga {$token[2]}: ", token_name($token[0]), " ('{$token[1]}')", PHP_EOL;
    }
}
?>


    &example.outputs.similar;


Riga 1: T_OPEN_TAG ('<?php ')
Riga 1: T_ECHO ('echo')
Riga 1: T_WHITESPACE (' ')
Riga 1: T_CLOSE_TAG ('?>')







    Esempio di uso errato di token_get_all


<?php
$tokens = token_get_all('/* commento */');

foreach ($tokens as $token) {
    if (is_array($token)) {
        echo "Riga {$token[2]}: ", token_name($token[0]), " ('{$token[1]}')", PHP_EOL;
    }
}
?>


    &example.outputs.similar;


Riga 1: T_INLINE_HTML ('/* commento */')



   Si noti nell'esempio precedente che la stringa viene analizzata come
   T_INLINE_HTML anziché come il previsto
   T_COMMENT. Questo accade perché nel codice fornito non è
   stato usato alcun tag di apertura. Equivale a inserire un commento al di
   fuori dei tag PHP in un normale file.





     Esempio di token_get_all su una classe che usa una parola riservata



<?php

$source = <<<'code'
<?php

class A
{
    const PUBLIC = 1;
}
code;

$tokens = token_get_all($source, TOKEN_PARSE);

foreach ($tokens as $token) {
    if (is_array($token)) {
        echo token_name($token[0]) , PHP_EOL;
    }
}
?>


    &example.outputs.similar;


T_OPEN_TAG
T_WHITESPACE
T_CLASS
T_WHITESPACE
T_STRING
T_CONST
T_WHITESPACE
T_STRING
T_LNUMBER



   Senza il flag TOKEN_PARSE, il penultimo
   token (T_STRING) sarebbe stato
   T_PUBLIC.
